using Astronomy.MediaFactory.Core.AstronomyDomain.Entities; using Astronomy.MediaFactory.Core.AstronomyDomain.Families; using Astronomy.MediaFactory.Core.AstronomyDomain.Localization; using Astronomy.MediaFactory.Core.AstronomyDomain.Relationships; using Astronomy.MediaFactory.Core.AstronomyDomain.Sources;
namespace Astronomy.MediaFactory.Core.AstronomyDomain.Validation;
public sealed class AstronomyDomainValidator(IAstronomyRelationshipPolicy relationshipPolicy):IAstronomyDomainValidator
{ static DomainValidationIssue E(string c,string m,string? p=null,string? e=null,string? f=null)=>new(c,m,DomainValidationSeverity.Error,p,e,f); static DomainValidationIssue W(string c,string m,string? p=null,string? e=null,string? f=null)=>new(c,m,DomainValidationSeverity.Warning,p,e,f);
 public DomainValidationResult ValidateEntity(IAstronomyDomainEntity entity){ArgumentNullException.ThrowIfNull(entity); var i=new List<DomainValidationIssue>(); var id=entity.Identity; if(string.IsNullOrWhiteSpace(id.EntityId)) i.Add(E("A2.DOMAIN.IDENTITY.EntityIdMissing","EntityId is required.","identity.entityId",familyId:id.FamilyId)); if(id.EntityId.Any(char.IsWhiteSpace)) i.Add(E("A2.DOMAIN.IDENTITY.EntityIdContainsWhitespace","EntityId must not contain whitespace.","identity.entityId",id.EntityId,id.FamilyId)); if(string.IsNullOrWhiteSpace(id.CanonicalName)) i.Add(E("A2.DOMAIN.IDENTITY.CanonicalNameMissing","CanonicalName is required.","identity.canonicalName",id.EntityId,id.FamilyId)); if(string.IsNullOrWhiteSpace(id.FamilyId)) i.Add(E("A2.DOMAIN.IDENTITY.FamilyIdMissing","FamilyId is required.","identity.familyId",id.EntityId)); if(id.Aliases.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=id.Aliases.Count) i.Add(E("A2.DOMAIN.IDENTITY.DuplicateAlias","Aliases must be unique.","identity.aliases",id.EntityId,id.FamilyId)); if(id.Aliases.Any(a=>string.Equals(a,id.CanonicalName,StringComparison.OrdinalIgnoreCase))) i.Add(E("A2.DOMAIN.IDENTITY.AliasDuplicatesCanonicalName","Alias must not duplicate canonical name.","identity.aliases",id.EntityId,id.FamilyId)); var locs=entity.Localizations.SelectMany(ValidateLocalization).ToList(); i.AddRange(locs); var dupLoc=entity.Localizations.GroupBy(l=>l.NormalizedLocale,StringComparer.OrdinalIgnoreCase).FirstOrDefault(g=>g.Count()>1); if(dupLoc!=null)i.Add(E("A2.DOMAIN.LOCALIZATION.DuplicateLocale","One localization per language/region is allowed.","localizations",id.EntityId,id.FamilyId)); foreach(var r in entity.Relationships)i.AddRange(ValidateRelationship(r).Issues); foreach(var s in entity.Sources)i.AddRange(ValidateSource(s).Issues); foreach(var k in entity.Metadata.ExtensionMetadata.Keys) if(Reserved.Contains(k)) i.Add(E("A2.DOMAIN.METADATA.ReservedExtensionKey","ExtensionMetadata must not redefine core fields.","metadata.extensionMetadata",id.EntityId,id.FamilyId)); return new(i.OrderBy(x=>x.Code).ThenBy(x=>x.Path).ToArray()); }
 static readonly HashSet<string> Reserved=new(StringComparer.OrdinalIgnoreCase){"entityId","canonicalName","familyId","classification","sources","relationships","localizations"};
 public DomainValidationResult ValidateFamily(IAstronomyDomainFamily family){ArgumentNullException.ThrowIfNull(family); var i=new List<DomainValidationIssue>(); if(string.IsNullOrWhiteSpace(family.FamilyId)) i.Add(E("A2.DOMAIN.FAMILY.FamilyIdMissing","FamilyId is required.","familyId")); if(family.SupportedEventTypeAliases.Any(string.IsNullOrWhiteSpace)) i.Add(E("A2.DOMAIN.FAMILY.EmptyAlias","EventType aliases cannot be empty.","supportedEventTypeAliases",familyId:family.FamilyId)); return new(i);}
 public DomainValidationResult ValidateRelationship(AstronomyRelationship r){ArgumentNullException.ThrowIfNull(r); var i=new List<DomainValidationIssue>(); if(string.IsNullOrWhiteSpace(r.SourceEntityId))i.Add(E("A2.DOMAIN.RELATIONSHIP.SourceMissing","SourceEntityId is required.","sourceEntityId")); if(string.IsNullOrWhiteSpace(r.TargetEntityId))i.Add(E("A2.DOMAIN.RELATIONSHIP.TargetMissing","TargetEntityId is required.","targetEntityId")); if(string.Equals(r.SourceEntityId,r.TargetEntityId,StringComparison.OrdinalIgnoreCase)&&!relationshipPolicy.AllowsSelfReference(r.RelationshipType))i.Add(E("A2.DOMAIN.RELATIONSHIP.SelfReference","Self-relationships are not allowed.","targetEntityId",r.SourceEntityId)); if(r.Confidence<0||r.Confidence>1)i.Add(E("A2.DOMAIN.RELATIONSHIP.ConfidenceOutOfRange","Confidence must be between 0 and 1.","confidence")); if(r.SourceIds.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=r.SourceIds.Count)i.Add(E("A2.DOMAIN.RELATIONSHIP.DuplicateSourceId","Source IDs must be unique.","sourceIds")); if(r.ValidTo<r.ValidFrom)i.Add(E("A2.DOMAIN.RELATIONSHIP.InvalidDateRange","ValidTo cannot precede ValidFrom.","validTo")); if(r.Direction==RelationshipDirection.Bidirectional&&!relationshipPolicy.AllowsBidirectional(r.RelationshipType))i.Add(E("A2.DOMAIN.RELATIONSHIP.InvalidBidirectionalType","Relationship type is not symmetric.","direction")); return new(i.OrderBy(x=>x.Code).ToArray());}
 public DomainValidationResult ValidateLocalization(AstronomyLocalizedContent l){ArgumentNullException.ThrowIfNull(l); var i=new List<DomainValidationIssue>(); if(string.IsNullOrWhiteSpace(l.LanguageCode))i.Add(E("A2.DOMAIN.LOCALIZATION.LanguageMissing","LanguageCode is required.","languageCode")); if(string.IsNullOrWhiteSpace(l.DisplayName))i.Add(E("A2.DOMAIN.LOCALIZATION.DisplayNameMissing","DisplayName is required.","displayName")); if(l.SearchAliases.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=l.SearchAliases.Count)i.Add(E("A2.DOMAIN.LOCALIZATION.DuplicateAlias","Aliases must be unique.","searchAliases")); if(l.IsMachineTranslated&&l.ReviewStatus==LocalizationReviewStatus.Approved)i.Add(E("A2.DOMAIN.LOCALIZATION.MachineTranslationApproved","Machine-translated records cannot be automatically approved.","reviewStatus")); return new(i.OrderBy(x=>x.Code).ToArray());}
 public DomainValidationResult ValidateSource(AstronomySourceReference s){ArgumentNullException.ThrowIfNull(s); var i=new List<DomainValidationIssue>(); if(string.IsNullOrWhiteSpace(s.SourceId))i.Add(E("A2.DOMAIN.SOURCE.SourceIdMissing","SourceId is required.","sourceId")); if(s.Url is { IsAbsoluteUri:false })i.Add(E("A2.DOMAIN.SOURCE.InvalidUrl","URL must be absolute.","url")); if(s.Url is not null && s.RetrievedUtc is null)i.Add(E("A2.DOMAIN.SOURCE.RetrievedUtcMissing","RetrievedUtc is required for web references.","retrievedUtc")); if(s.SourceType==AstronomySourceType.GeneralReference&&s.Reliability==SourceReliability.Authoritative)i.Add(W("A2.DOMAIN.SOURCE.GeneralReferenceAuthoritative","General references are not automatically authoritative.","reliability")); return new(i.OrderBy(x=>x.Code).ToArray());}
}
